        /// <para>An <c>SDL_AsyncIOQueue</c> must be specified. The newly-created task will be added to it when it completes its work.</para>
        /// </remarks>
        /// <param name="asyncio">a pointer to an <c>SDL_AsyncIO</c> structure to close.</param>
        /// <param name="flush">true if data should sync to disk before the task completes.</param>
